typedef struct trie {
    struct trie *kid[26];
    int is_word;
} trie;
trie *make(void) {
    return calloc(1, sizeof(trie));
}

void add(trie *t, const char *w) {
    for (; *w; w++) {
        int i = *w - 'a';
        if (t->kid[i] == NULL)
            t->kid[i] = make();
        t = t->kid[i];
    }
    t->is_word = 1;
}

int has(trie *t, const char *w) {
    for (; *w; w++) {
        t = t->kid[*w - 'a'];
        if (t == NULL)
            return 0;
    }
    return t->is_word;
}
